INSERT INTO faqs (faq_id, question, answer, keywords, category) VALUES
('F1001','如何修改收货地址？','订单未发货前，您可以在「我的订单-订单详情」中点击修改收货地址；已发货订单无法修改地址，可联系快递员改址或申请拒收后退回。','["地址","改地址","收货","修改地址"]'::jsonb,'订单'),
('F1002','订单多久发货？','现货商品一般在支付成功后 24 小时内发货，偏远地区可能延迟 1-2 天；预售商品以商品页标注的发货时间为准。发货后会推送短信与物流单号。','["发货","多久","发货时间","时效"]'::jsonb,'订单'),
('F1003','支持哪些支付方式？','目前支持微信支付、支付宝、云闪付以及主流银行卡。暂不支持货到付款。','["支付","付款","微信","支付宝","银行卡"]'::jsonb,'支付'),
('F1004','退款多久到账？','退款审核通过后，原路退回：微信/支付宝一般 1-3 个工作日到账，银行卡 3-7 个工作日到账。节假日可能会有顺延。','["退款","到账","退款时间","退钱"]'::jsonb,'售后'),
('F1005','7天无理由退货是什么规则？','商品签收后 7 天内，保持商品完好、吊牌未剪、配件齐全，可申请无理由退货。定制类、生鲜类、贴身衣物等特殊商品不支持无理由退货，会在商品页标注。','["7天","无理由","退货","退换"]'::jsonb,'售后'),
('F1006','如何开具发票？','在「我的订单-开具发票」中提交抬头信息即可开具电子普票，1 个工作日内发送到您的邮箱；增值税专用发票请联系客服人工处理。','["发票","开票","报销","抬头"]'::jsonb,'订单'),
('F1007','App 打不开或闪退怎么办？','请依次尝试：1) 更新 App 到最新版本；2) 清除 App 缓存（设置-通用-存储空间）；3) 检查手机系统是否为受支持版本（iOS 13+/Android 8+）；4) 卸载重装。若仍无法解决，请转人工客服远程协助。','["闪退","打不开","崩溃","app","白屏"]'::jsonb,'技术'),
('F1008','登录收不到验证码怎么办？','请检查手机短信是否被拦截（垃圾短信/骚扰拦截），确认手机号正确且信号正常；验证码 60 秒内只能获取一次。若 10 分钟仍未收到，可使用语音验证码或更换登录方式。','["验证码","登录","收不到","短信"]'::jsonb,'技术'),
('F1009','支付成功但订单显示未支付？','可能是银行回调延迟，请等待 5-10 分钟后刷新订单页。若仍显示未支付但已被扣款，系统会在 24 小时内自动对账修复；超时未修复的款项将原路退回，也可联系客服人工核查。','["支付","未支付","扣款","掉单"]'::jsonb,'支付'),
('F1010','如何查询物流进度？','在「我的订单」中点击订单即可查看实时物流轨迹；也可以直接把订单号发给智能客服（如 SO10001），我可以帮您查询。','["物流","快递","进度","到哪了","轨迹"]'::jsonb,'订单'),
('F1011','收到的商品有质量问题怎么办？','很抱歉给您带来不好的体验！请在签收后 48 小时内拍照留存，在订单页申请「质量问题退货」，审核通过后包邮退回并全额退款，运费由平台承担。','["质量问题","破损","坏了","瑕疵","次品"]'::jsonb,'售后'),
('F1012','可以修改或取消订单吗？','未发货订单可在订单详情页自行取消后重新下单；已发货订单无法取消，可在签收后申请退货退款。','["取消订单","取消","改单","撤单"]'::jsonb,'订单'),
('F1013','会员积分有什么用？怎么获得？','每消费 1 元获得 1 积分，评价晒单、每日签到也可获得积分。积分可在下单时按 100:1 抵扣现金，也可在积分商城兑换优惠券和礼品。','["积分","会员","签到","兑换"]'::jsonb,'会员'),
('F1014','优惠券怎么使用？为什么用不了？','下单确认页点击「优惠券」选择即可抵扣。用不了的常见原因：未满足最低消费金额、商品不在适用范围、已过有效期、与限时折扣活动互斥。','["优惠券","券","抵扣","用不了"]'::jsonb,'支付'),
('F1015','如何注销账号？','在「设置-账号与安全-注销账号」中提交申请，需满足无进行中订单、无未结退款两个条件。注销后账号数据将在 15 天冷静期后删除，期间登录可撤销注销。','["注销","删除账号","销号"]'::jsonb,'账号'),
('F1016','怎么联系人工客服？','您可以直接在对话框输入「转人工」，系统会为您接通人工坐席；也可以预约电话回访，我们会主动外呼联系您。服务时间 9:00-21:00。','["人工","真人","客服","投诉","电话"]'::jsonb,'服务');
